assert.deepEqual(
    findStaleThemeOutputs(outputs, (file) =>
      file.endsWith(".json") ? current[file] : `${current[file]} `,
    ),
    ["src/styles/theme-kappa.css is stale"],
  )

assert.deepEqual(version.sections[0].entries.map(({ hash, text }) => ({ hash, text })), [
      { hash: "", text: "Initial code snapshot.\n  Includes components and application blocks." },
    ])

assert.doesNotThrow(() =>
    validateVersionedRelease({
      baseVersion: "0.2.0",
      changelog,
      currentVersion: "0.3.0",
      registryVersion: "0.3.0",
    }),
  )

assert.throws(
    () =>
      validateVersionedRelease({
        baseVersion: "0.3.0",
        changelog,
        currentVersion: "0.3.0",
        registryVersion: "0.3.0",
      }),
    /must be newer/,
  )

assert.throws(
    () =>
      validateVersionedRelease({
        baseVersion: "0.2.0",
        changelog,
        currentVersion: "0.3.0-beta.1",
        registryVersion: "0.3.0-beta.1",
      }),
    /stable semantic version/,
  )

assert.throws(
    () =>
      validateVersionedRelease({
        baseVersion: "0.2.0",
        changelog,
        currentVersion: "0.3.0",
        registryVersion: "0.2.0",
      }),
    /does not match/,
  )

